const muscleLibrary={
 peitoral:{label:'Peitoral',exercises:['Supino reto com barra','Supino reto com halteres','Supino inclinado com barra','Supino inclinado 30° com halteres','Supino declinado com halteres','Supino sentado na máquina','Voador peitoral','Crucifixo crossover na polia alta']},
 deltoide:{label:'Ombros · deltoides',exercises:['Desenvolvimento com halteres','Elevação lateral','Elevação frontal','Crucifixo inverso']},
 biceps:{label:'Bíceps',exercises:['Rosca direta','Rosca alternada','Rosca martelo','Rosca Scott']},
 triceps:{label:'Tríceps',exercises:['Tríceps na polia','Tríceps corda','Tríceps francês','Tríceps testa']},
 antebraco:{label:'Antebraços',exercises:['Rosca de punho','Rosca de punho inversa','Rosca inversa','Caminhada do fazendeiro']},
 abdomen:{label:'Abdômen · reto abdominal',exercises:['Abdominal no solo','Abdominal na polia','Elevação de pernas','Prancha abdominal']},
 obliquos:{label:'Oblíquos',exercises:['Prancha lateral','Abdominal oblíquo','Rotação de tronco na polia']},
 quadriceps:{label:'Quadríceps',exercises:['Agachamento livre com barra','Agachamento frontal','Agachamento no Smith','Agachamento goblet','Agachamento hack','Belt squat','Cadeira extensora']},
 adutores:{label:'Adutores',exercises:['Cadeira adutora','Adução de quadril na polia','Agachamento sumô']},
 tibial:{label:'Tibial anterior',exercises:['Elevação da ponta dos pés','Dorsiflexão com elástico']},
 trapezio:{label:'Trapézio',exercises:['Encolhimento com halteres','Encolhimento com barra','Face pull']},
 dorsais:{label:'Dorsais',exercises:['Puxada frontal','Barra fixa','Remada unilateral','Pulldown na polia']},
 romboides:{label:'Romboides · costas médias',exercises:['Remada baixa','Remada curvada','Remada com apoio no peito']},
 lombar:{label:'Lombar · eretores da coluna',exercises:['Extensão lombar no banco','Bird dog','Levantamento terra']},
 gluteos:{label:'Glúteos',exercises:['Elevação pélvica','Coice na polia','Cadeira abdutora','Afundo']},
 posteriores:{label:'Posteriores da coxa',exercises:['Mesa flexora','Cadeira flexora','Stiff com halteres','Levantamento terra romeno']},
 panturrilhas:{label:'Panturrilhas',exercises:['Panturrilha em pé','Panturrilha sentada','Panturrilha no leg press']}
};
let selectedMuscle='peitoral',bodySide='frente';
const muscleExerciseVideos={peitoral:['videos/chest/supino-reto-barra.mp4','videos/chest/supino-reto-halteres.mp4','videos/chest/supino-inclinado-barra.mp4','videos/chest/supino-inclinado-30-halteres.mp4','videos/chest/supino-declinado-halteres.mp4','videos/chest/supino-sentado-maquina.mp4','videos/chest/voador-peitoral.mp4','videos/chest/crucifixo-crossover-alto.mp4'],quadriceps:['videos/legs/agachamento-livre-barra.mp4','videos/legs/agachamento-frontal.mp4','videos/legs/agachamento-smith.mp4','videos/legs/agachamento-goblet.mp4','videos/legs/agachamento-hack.mp4','videos/legs/belt-squat.mp4','videos/legs/cadeira-extensora.mp4']};
const frontShapes={peitoral:['M91 85L118 83V119L90 113Z','M122 83L149 85L150 113L122 119Z'],deltoide:['M77 79L92 82L88 109L67 102Z','M148 82L163 79L173 102L152 109Z'],biceps:['M66 106L84 113L76 150L57 142Z','M156 113L174 106L183 142L164 150Z'],antebraco:['M56 146L74 155L58 195L44 189Z','M166 155L184 146L196 189L182 195Z'],abdomen:['M105 124H135L137 179L120 192L103 179Z'],obliquos:['M89 121L100 124L98 175L88 163Z','M140 124L151 121L152 163L142 175Z'],quadriceps:['M88 203L106 205L108 271L87 278L78 239Z','M134 205L152 203L162 239L153 278L132 271Z'],adutores:['M110 205L119 211L115 251L110 272Z','M121 211L130 205L130 272L125 251Z'],tibial:['M87 291L98 291L91 346L82 346Z','M142 291L153 291L158 346L149 346Z']};
const backShapes={trapezio:['M103 68L120 77L137 68L151 86L120 107L89 86Z'],deltoide:['M76 80L90 84L87 109L67 103Z','M150 84L164 80L173 103L153 109Z'],triceps:['M66 108L84 113L75 151L57 143Z','M156 113L174 108L183 143L165 151Z'],antebraco:frontShapes.antebraco,dorsais:['M89 110L108 121L111 163L91 154Z','M132 121L151 110L149 154L129 163Z'],romboides:['M106 103L118 110V135L109 126Z','M122 110L134 103L131 126L122 135Z'],lombar:['M109 140L120 136L131 140L137 177L120 186L103 177Z'],gluteos:['M91 182L118 187V219L88 222L81 203Z','M122 187L149 182L159 203L152 222L122 219Z'],posteriores:['M85 228L111 227L108 279L86 278L78 247Z','M129 227L155 228L162 247L154 278L132 279Z'],panturrilhas:['M85 288L107 288L105 315L91 342L81 336Z','M133 288L155 288L159 336L149 342L135 315Z']};
function muscleBody(){const shapes=bodySide==='frente'?frontShapes:backShapes;return `<svg viewBox="0 0 240 390" class="muscle-body" role="group" aria-label="Mapa muscular · ${bodySide}"><ellipse cx="120" cy="39" rx="23" ry="27" fill="#58644d"/><path d="M105 63L102 74L77 79L64 101L52 148L39 190L40 208L51 212L61 196L80 154L86 117L88 166L79 204L74 248L80 288L74 350L68 365L95 365L104 347L113 292L120 246L127 292L136 347L145 365L172 365L166 350L160 288L166 248L161 204L152 166L154 117L160 154L179 196L189 212L200 208L201 190L188 148L176 101L163 79L138 74L135 63Z" fill="#30392b" stroke="#657158" stroke-width="1.5"/>${Object.entries(shapes).map(([key,paths])=>`<g tabindex="0" role="button" aria-label="${muscleLibrary[key].label}" aria-pressed="${selectedMuscle===key}" class="muscle-region ${selectedMuscle===key?'selected':''}" onclick="chooseMuscle('${key}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();chooseMuscle('${key}')}" data-muscle="${key}"><title>${muscleLibrary[key].label}</title>${paths.map(d=>`<path d="${d}"/>`).join('')}</g>`).join('')}<path d="M120 85V179M120 225V245" stroke="#172012" stroke-width="2" pointer-events="none"/></svg>`}
function musclePicker(){return `<section class="card muscle-picker" aria-labelledby="muscle-heading"><div class="row"><div><span class="eyebrow">MONTE O TREINO PELO MÚSCULO</span><h2 id="muscle-heading">Onde vamos trabalhar?</h2><p>Clique no corpo ou selecione um grupo muscular.</p></div><span class="tag">${Object.keys(muscleLibrary).length} GRUPOS</span></div><div class="muscle-layout"><div class="body-panel"><div class="login-tabs"><button class="${bodySide==='frente'?'primary':''}" aria-pressed="${bodySide==='frente'}" onclick="changeBodySide('frente')">Frente</button><button class="${bodySide==='costas'?'primary':''}" aria-pressed="${bodySide==='costas'}" onclick="changeBodySide('costas')">Costas</button></div>${muscleBody()}<p class="note">Mapa esquemático dos principais grupos usados na musculação.</p></div><div class="muscle-options"><div class="muscle-chips">${Object.entries(muscleLibrary).map(([k,m])=>`<button aria-pressed="${selectedMuscle===k}" class="${selectedMuscle===k?'primary':''}" onclick="chooseMuscle('${k}')">${m.label}</button>`).join('')}</div><div id="muscle-exercises" aria-live="polite">${muscleFilters()}<div class="row"><h3>${muscleLibrary[selectedMuscle].label}</h3><span class="muted">${muscleLibrary[selectedMuscle].exercises.length} opções</span></div>${muscleLibrary[selectedMuscle].exercises.map((name,i)=>({name,i})).filter(({i})=>!selectedPortion||muscleLibrary[selectedMuscle].portions?.[i]===selectedPortion).map(({name,i})=>`<div class="exercise"><span class="num">${String(i+1).padStart(2,'0')}</span><div class="details"><b>${esc(name)}</b>${muscleLibrary[selectedMuscle].portions?.[i]?`<p style="color:var(--green);font-size:10px">${esc(muscleLibrary[selectedMuscle].portions[i])}</p>`:""}<p>Defina séries, repetições, carga e descanso.</p>${muscleExerciseVideos[selectedMuscle]?.[i]?`<video class="muscle-demo-video" controls preload="none" playsinline aria-label="Demonstração: ${esc(name)}"><source src="${muscleExerciseVideos[selectedMuscle][i]}" type="video/mp4">Seu navegador não reproduz este vídeo.</video><span class="video-caption">Demonstração do exercício</span>`:''}</div><button class="primary" onclick="pickMuscleExercise('${selectedMuscle}',${i})">+ Adicionar</button></div>`).join('')}<button class="custom-exercise" onclick="editExercise()">+ Cadastrar outro exercício</button></div></div></div></section>`}
window.chooseMuscle=key=>{if(!muscleLibrary[key]||role!=='personal')return;selectedMuscle=key;if(!Object.hasOwn(bodySide==='frente'?frontShapes:backShapes,key))bodySide=bodySide==='frente'?'costas':'frente';render()};
window.changeBodySide=side=>{if(!['frente','costas'].includes(side))return;bodySide=side;const shapes=side==='frente'?frontShapes:backShapes;if(!Object.hasOwn(shapes,selectedMuscle))selectedMuscle=Object.keys(shapes)[0];render()};
window.pickMuscleExercise=(key,index)=>{if(role!=='personal')return;const name=muscleLibrary[key]?.exercises[index];if(!name)return;window.editExercise(undefined,{name,sets:3,reps:12,weight:0,rest:60,gif:'',muscle:key})};
const originalRender=render;render=function(){originalRender();if(role==='personal'&&page==='treinos'){$('#content').insertAdjacentHTML('afterbegin',musclePicker());const picker=$('.muscle-picker');$('#content').children[1].after(picker)}};



